   223→// --- Compose override generation ---
   224→
   225→type composeOverride struct {
   226→	Services map[string]serviceOverride `yaml:"services"`
   227→	Networks map[string]networkDef      `yaml:"networks,omitempty"`
   228→	Secrets  map[string]secretFileDef   `yaml:"secrets,omitempty"`
   229→}
   230→
   231→type serviceOverride struct {
   232→	Labels   map[string]string `yaml:"labels,omitempty"`
   233→	EnvFile  []string          `yaml:"env_file,omitempty"`
   234→	Secrets  []string          `yaml:"secrets,omitempty"`
   235→	Networks []string          `yaml:"networks,omitempty"`
   236→}
   237→
   238→type networkDef struct {
   239→	External bool `yaml:"external"`
   240→}
   241→
   242→type secretFileDef struct {
   243→	File string `yaml:"file"`
   244→}
   245→
   246→type minimalCompose struct {
   247→	Services map[string]minimalService `yaml:"services"`
   248→}
   249→
   250→type minimalService struct {
   251→	Expose []any `yaml:"expose"`
   252→	Ports  []any `yaml:"ports"`
   253→}
   254→
   255→func (d *Deployer) generateOverride(
   256→	root *os.Root,
   257→	appDir, appName string,
   258→	app config.App,
   259→	repoDir, composeFile string,
   260→	dockerSecrets map[string]string,
   261→) error {
   262→	// Detect service name and port from the app's compose file.
   263→	serviceName, port, err := detectServiceInfo(filepath.Join(repoDir, composeFile), appName)
   264→	if err != nil {
   265→		d.Logger.Warn("could not detect service info, using defaults",
   266→			"app", appName, "error", err)
   267→		serviceName = "app"
   268→		port = "3000"
   269→	}
   270→
   271→	svc := serviceOverride{
   272→		Labels: map[string]string{
   273→			"caddy":               app.Domain,
   274→			"caddy.reverse_proxy": fmt.Sprintf("{{upstreams %s}}", port),
   275→		},
   276→		Networks: []string{"caddy"},
   277→	}
   278→
   279→	if app.EnvFile != "" {
   280→		svc.EnvFile = []string{app.EnvFile}
   281→	}
   282→
   283→	secretNames := slices.Sorted(maps.Keys(dockerSecrets))
   284→	if len(secretNames) > 0 {
   285→		svc.Secrets = secretNames
   286→	}
   287→
   288→	override := composeOverride{
   289→		Services: map[string]serviceOverride{serviceName: svc},
   290→		Networks: map[string]networkDef{"caddy": {External: true}},
   291→	}
   292→
   293→	if len(secretNames) > 0 {
   294→		override.Secrets = make(map[string]secretFileDef, len(secretNames))
   295→		for _, name := range secretNames {
   296→			override.Secrets[name] = secretFileDef{
   297→				File: filepath.Join(appDir, "secrets", name),
   298→			}
   299→		}
   300→	}
   301→
   302→	data, err := yaml.Marshal(override)
   303→	if err != nil {
   304→		return fmt.Errorf("marshaling override: %w", err)
   305→	}
   306→
   307→	// If app has inline override YAML, deep-merge it.
   308→	if app.Override != "" {
   309→		var baseMap, overlayMap map[string]any
   310→		if err := yaml.Unmarshal(data, &baseMap); err != nil {
   311→			return fmt.Errorf("re-parsing generated override: %w", err)
   312→		}
   313→		if err := yaml.Unmarshal([]byte(app.Override), &overlayMap); err != nil {
   314→			return fmt.Errorf("parsing app override YAML: %w", err)
   315→		}
   316→		merged := deepMerge(baseMap, overlayMap)
   317→		data, err = yaml.Marshal(merged)
   318→		if err != nil {
   319→			return fmt.Errorf("marshaling merged override: %w", err)
   320→		}
   321→	}
   322→
   323→	f, err := root.OpenFile("compose.override.yml", os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0644)
   324→	if err != nil {
   325→		return err
   326→	}
   327→	defer f.Close()
   328→	_, err = f.Write(data)
   329→	return err
   330→}
