    33→// CheckPrerequisites verifies all system prerequisites are met.
    34→func CheckPrerequisites(ctx context.Context, w io.Writer, dataDir string) error {
    35→	fmt.Fprintln(w, "Checking prerequisites...")
    36→
    37→	// 1. Docker
    38→	dockerVersion, err := checkDocker(ctx)
    39→	if err != nil {
    40→		fmt.Fprintf(w, "  Docker:          ✗ not found\n")
    41→		return fmt.Errorf("Docker is not installed or not accessible. Install Docker and ensure the current user is in the 'docker' group.")
    42→	}
    43→	fmt.Fprintf(w, "  Docker:          ✓ %s\n", dockerVersion)
    44→
    45→	// 2. Docker Compose
    46→	composeVersion, err := checkDockerCompose(ctx)
    47→	if err != nil {
    48→		fmt.Fprintf(w, "  Docker Compose:  ✗ not found\n")
    49→		return fmt.Errorf("Docker Compose plugin is not installed.")
    50→	}
    51→	fmt.Fprintf(w, "  Docker Compose:  ✓ %s\n", composeVersion)
    52→
    53→	// 3. Git
    54→	gitVersion, err := checkGit(ctx)
    55→	if err != nil {
    56→		fmt.Fprintf(w, "  Git:             ✗ not found\n")
    57→		return fmt.Errorf("git is not installed.")
    58→	}
    59→	fmt.Fprintf(w, "  Git:             ✓ %s\n", gitVersion)
    60→
    61→	// 4. Ports 80/443
    62→	portsOK, err := checkPorts(ctx)
    63→	if err != nil || !portsOK {
    64→		fmt.Fprintf(w, "  Ports 80/443:    ✗ in use\n")
    65→		return fmt.Errorf("Ports 80/443 are in use. Stop the existing proxy before running init.")
    66→	}
    67→	fmt.Fprintf(w, "  Ports 80/443:    ✓ available\n")
    68→
    69→	// 5. Data dir
    70→	if err := checkDataDir(dataDir); err != nil {
    71→		fmt.Fprintf(w, "  Data directory:  ✗ %s\n", dataDir)
    72→		return err
    73→	}
    74→	fmt.Fprintf(w, "  Data directory:  ✓ %s (writable)\n", dataDir)
    75→
    76→	return nil
    77→}
