    79→func checkDocker(ctx context.Context) (string, error) {
    80→	out, err := exec.CommandContext(ctx, "docker", "info", "--format", "Docker {{.ServerVersion}}").Output()
    81→	if err != nil {
    82→		return "", err
    83→	}
    84→	return strings.TrimSpace(string(out)), nil
    85→}
    86→
    87→func checkDockerCompose(ctx context.Context) (string, error) {
    88→	out, err := exec.CommandContext(ctx, "docker", "compose", "version", "--short").Output()
    89→	if err != nil {
    90→		return "", err
    91→	}
    92→	v := strings.TrimSpace(string(out))
    93→	if !strings.HasPrefix(v, "v") {
    94→		v = "v" + v
    95→	}
    96→	return v, nil
    97→}
