    99→func checkGit(ctx context.Context) (string, error) {
   100→	out, err := exec.CommandContext(ctx, "git", "--version").Output()
   101→	if err != nil {
   102→		return "", err
   103→	}
   104→	// "git version 2.43.0" -> "2.43.0"
   105→	parts := strings.Fields(string(out))
   106→	if len(parts) >= 3 {
   107→		return parts[2], nil
   108→	}
   109→	return strings.TrimSpace(string(out)), nil
   110→}
