   112→// checkPorts returns true if ports 80 and 443 are free.
   113→func checkPorts(ctx context.Context) (bool, error) {
   114→	out, err := exec.CommandContext(ctx, "ss", "-tlnp").Output()
   115→	if err != nil {
   116→		// ss not available — skip check, assume free
   117→		return true, nil
   118→	}
   119→	for _, line := range strings.Split(string(out), "\n") {
   120→		if strings.Contains(line, ":80 ") || strings.Contains(line, ":443 ") {
   121→			return false, nil
   122→		}
   123→	}
   124→	return true, nil
   125→}
