   127→func checkDataDir(dataDir string) error {
   128→	info, err := os.Stat(dataDir)
   129→	if errors.Is(err, os.ErrNotExist) {
   130→		if mkErr := os.MkdirAll(dataDir, 0700); mkErr != nil {
   131→			return fmt.Errorf("data directory %q does not exist and could not be created.\nRun: sudo mkdir -p %s && sudo chown $(whoami) %s",
   132→				dataDir, dataDir, dataDir)
   133→		}
   134→		return nil
   135→	}
   136→	if err != nil {
   137→		return fmt.Errorf("data directory %q: %w", dataDir, err)
   138→	}
   139→	if !info.IsDir() {
   140→		return fmt.Errorf("data directory %q is not a directory", dataDir)
   141→	}
   142→	testFile := filepath.Join(dataDir, ".write_test")
   143→	f, err := os.OpenFile(testFile, os.O_CREATE|os.O_WRONLY, 0600)
   144→	if err != nil {
   145→		return fmt.Errorf("data directory %q is not writable.\nRun: sudo chown $(whoami) %s", dataDir, dataDir)
   146→	}
   147→	f.Close()
   148→	os.Remove(testFile)
   149→	return nil
   150→}
