   152→// Bootstrap runs the full server initialisation sequence.
   153→func Bootstrap(ctx context.Context, w io.Writer, opts Options) error {
   154→	if opts.HeraldPort == 0 {
   155→		opts.HeraldPort = 8080
   156→	}
   157→
   158→	// Step 1: Clone server IaC repo
   159→	repoDir := filepath.Join(opts.DataDir, "repo")
   160→	configPath := filepath.Join(repoDir, "config.yml")
   161→
   162→	fmt.Fprintln(w, "\nCloning server repository...")
   163→	if err := cloneOrPull(ctx, w, opts.ServerRepo, repoDir, opts.GitHubToken); err != nil {
   164→		return fmt.Errorf("cloning server repo: %w", err)
   165→	}
   166→
   167→	// Step 2: Load and validate config
   168→	fmt.Fprintln(w, "\nLoading configuration...")
   169→	fmt.Fprintf(w, "  → %s\n", configPath)
   170→	cfg, err := config.Load(configPath)
   171→	if err != nil {
   172→		return fmt.Errorf("loading config: %w", err)
   173→	}
   174→	if opts.StacksDir != "" {
   175→		cfg.Server.StacksDir = opts.StacksDir
   176→	}
   177→	fmt.Fprintf(w, "  ✓ Config loaded: %d app%s, %d stack%s\n",
   178→		len(cfg.Apps), plural(len(cfg.Apps)),
   179→		len(cfg.Stacks), plural(len(cfg.Stacks)))
   180→
   181→	// Step 3: Initialize secrets store
   182→	fmt.Fprintln(w, "\nInitializing secrets store...")
   183→	store := secrets.NewStore(opts.DataDir)
   184→	ageKeyPath := filepath.Join(opts.DataDir, "age.key")
   185→	_, statErr := os.Stat(ageKeyPath)
   186→	keyExists := statErr == nil
   187→	if err := store.Init(); err != nil {
   188→		return fmt.Errorf("initializing secrets store: %w", err)
   189→	}
   190→	if !keyExists {
   191→		fmt.Fprintf(w, "  → Generated age key: %s\n", ageKeyPath)
   192→		fmt.Fprintln(w, "  ✓ Secrets store initialized")
   193→		fmt.Fprintf(w, "  ⚠ IMPORTANT: Back up %s — it cannot be recovered if lost!\n", ageKeyPath)
   194→	} else {
   195→		fmt.Fprintf(w, "  → Age key already exists: %s\n", ageKeyPath)
   196→		fmt.Fprintln(w, "  ✓ Secrets store ready")
   197→	}
   198→
   199→	// Step 4: Set webhook secret
   200→	fmt.Fprintln(w, "\nConfiguring webhook secret...")
   201→	if _, getErr := store.Get("herald/webhook_secret"); getErr != nil {
   202→		secret, err := generateSecret()
   203→		if err != nil {
   204→			return fmt.Errorf("generating webhook secret: %w", err)
   205→		}
   206→		if err := store.Set("herald/webhook_secret", secret); err != nil {
   207→			return fmt.Errorf("storing webhook secret: %w", err)
   208→		}
   209→		fmt.Fprintln(w, "  → Generated webhook secret")
   210→		fmt.Fprintln(w, "  ✓ Webhook secret stored in secrets store")
   211→	} else {
   212→		fmt.Fprintln(w, "  → Webhook secret already exists, skipping")
   213→		fmt.Fprintln(w, "  ✓ Webhook secret ready")
   214→	}
   215→
   216→	// Step 5: Store GitHub token
   217→	if opts.GitHubToken != "" {
   218→		fmt.Fprintln(w, "\nStoring GitHub token...")
   219→		if err := store.Set("herald/github_token", opts.GitHubToken); err != nil {
   220→			return fmt.Errorf("storing GitHub token: %w", err)
   221→		}
   222→		fmt.Fprintln(w, "  ✓ GitHub token stored in secrets store")
   223→	}
   224→
   225→	// Step 6: Create directories
   226→	fmt.Fprintln(w, "\nCreating directories...")
   227→	dirs := []string{
   228→		filepath.Join(cfg.Server.StacksDir, "apps"),
   229→		filepath.Join(cfg.Server.StacksDir, "stacks"),
   230→		filepath.Join(cfg.Server.StacksDir, "envs"),
   231→	}
   232→	for _, d := range dirs {
   233→		fmt.Fprintf(w, "  → %s/\n", d)
   234→		if err := os.MkdirAll(d, 0755); err != nil {
   235→			return fmt.Errorf("creating directory %s: %w", d, err)
   236→		}
   237→	}
   238→	fmt.Fprintln(w, "  ✓ Directories created")
   239→
   240→	// Step 7: Start Caddy
   241→	fmt.Fprintln(w, "\nStarting Caddy reverse proxy...")
   242→	caddyMgr := &caddy.CaddyManager{
   243→		Config:     cfg,
   244→		Logger:     slog.Default(),
   245→		HeraldPort: opts.HeraldPort,
   246→	}
   247→	running, _ := caddyMgr.IsRunning(ctx)
   248→	if running {
   249→		fmt.Fprintln(w, "  → Caddy already running, skipping")
   250→		fmt.Fprintln(w, "  ✓ Caddy running on :80/:443")
   251→	} else {
   252→		fmt.Fprintln(w, "  → Creating 'caddy' Docker network")
   253→		fmt.Fprintln(w, "  → Starting caddy-docker-proxy")
   254→		if err := caddyMgr.Start(ctx); err != nil {
   255→			return fmt.Errorf("starting Caddy: %w", err)
   256→		}
   257→		fmt.Fprintln(w, "  ✓ Caddy running on :80/:443")
   258→	}
   259→
   260→	// Step 8: Register GitHub webhooks
   261→	fmt.Fprintln(w, "\nRegistering GitHub webhooks...")
   262→	token := opts.GitHubToken
   263→	if token == "" {
   264→		token = cfg.Server.GithubToken
   265→	}
   266→	if token != "" {
   267→		ghClient := github.NewGitHubClient(token, slog.Default())
   268→
   269→		results, err := github.SyncWebhooks(ctx, cfg, store, ghClient)
   270→		if err != nil {
   271→			return fmt.Errorf("syncing webhooks: %w", err)
   272→		}
   273→
   274→		// Also register on the server IaC repo itself if not already covered.
   275→		serverResult := syncServerRepoWebhook(ctx, cfg, ghClient, store, opts.ServerRepo)
   276→		results = append(results, serverResult)
   277→
   278→		registered := 0
   279→		for _, r := range results {
   280→			suffix := ""
   281→			if r.Repo == opts.ServerRepo {
   282→				suffix = " (self-update)"
   283→			}
   284→			switch r.Action {
   285→			case "created":
   286→				fmt.Fprintf(w, "  → %-24s + created%s\n", r.Repo, suffix)
   287→				registered++
   288→			case "exists":
   289→				fmt.Fprintf(w, "  → %-24s ✓ exists%s\n", r.Repo, suffix)
   290→				registered++
   291→			case "error":
   292→				fmt.Fprintf(w, "  → %-24s ✗ %v\n", r.Repo, r.Error)
   293→			}
   294→		}
   295→		fmt.Fprintf(w, "  ✓ %d webhook%s registered\n", registered, plural(registered))
   296→	} else {
   297→		fmt.Fprintln(w, "  → No GitHub token provided, skipping webhook registration")
   298→	}
   299→
   300→	// Step 9: Clone app repositories
   301→	fmt.Fprintln(w, "\nCloning app repositories...")
   302→	appNames := slices.Sorted(maps.Keys(cfg.Apps))
   303→	cloned := 0
   304→	for _, appName := range appNames {
   305→		app := cfg.Apps[appName]
   306→		appRepoDir := filepath.Join(cfg.Server.StacksDir, "apps", appName, "repo")
   307→		fmt.Fprintf(w, "  → %-10s %s:%s → %s\n", appName, app.Repo, app.Branch, appRepoDir)
   308→		if err := os.MkdirAll(filepath.Dir(appRepoDir), 0755); err != nil {
   309→			fmt.Fprintf(w, "    ✗ %v\n", err)
   310→			continue
   311→		}
   312→		cloneToken := token
   313→		if err := cloneOrPullBranch(ctx, app.Repo, app.Branch, appRepoDir, cloneToken); err != nil {
   314→			fmt.Fprintf(w, "    ✗ %v\n", err)
   315→		} else {
   316→			cloned++
   317→		}
   318→	}
   319→	fmt.Fprintf(w, "  ✓ %d repositor%s cloned\n", cloned, pluralIes(cloned))
   320→
   321→	printCompletion(w, cfg, opts)
   322→	return nil
   323→}
   324→
   325→// cloneOrPull clones a repo or pulls the latest if already cloned.
   326→func cloneOrPull(ctx context.Context, w io.Writer, repo, destDir, token string) error {
   327→	if _, err := os.Stat(filepath.Join(destDir, ".git")); err == nil {
   328→		fmt.Fprintln(w, "  → Repository already cloned, pulling latest...")
   329→		cmd := exec.CommandContext(ctx, "git", "-C", destDir, "pull")
   330→		var out strings.Builder
   331→		cmd.Stdout = &out
   332→		cmd.Stderr = &out
   333→		if err := cmd.Run(); err != nil {
   334→			return fmt.Errorf("git pull: %w: %s", err, strings.TrimSpace(out.String()))
   335→		}
   336→		fmt.Fprintln(w, "  ✓ Repository updated")
   337→		return nil
   338→	}
   339→
   340→	displayURL := fmt.Sprintf("https://github.com/%s.git", repo)
   341→	fmt.Fprintf(w, "  → git clone %s %s\n", displayURL, destDir)
   342→
   343→	cloneURL := buildCloneURL(token, repo)
   344→	cmd := exec.CommandContext(ctx, "git", "clone", cloneURL, destDir)
   345→	var stderr strings.Builder
   346→	cmd.Stderr = &stderr
   347→	if err := cmd.Run(); err != nil {
   348→		stderrStr := strings.TrimSpace(stderr.String())
   349→		if strings.Contains(stderrStr, "not found") || strings.Contains(stderrStr, "Repository not found") {
   350→			return fmt.Errorf("cannot clone %s. If this is a private repo, provide --github-token", repo)
   351→		}
   352→		if stderrStr != "" {
   353→			return fmt.Errorf("git clone: %w: %s", err, stderrStr)
   354→		}
   355→		return fmt.Errorf("git clone: %w", err)
   356→	}
   357→	fmt.Fprintln(w, "  ✓ Repository cloned")
   358→	return nil
   359→}
   360→
   361→// cloneOrPullBranch clones a specific branch or updates it if already cloned.
   362→func cloneOrPullBranch(ctx context.Context, repo, branch, destDir, token string) error {
